let language='pt';
function preferredLanguage(locales=[]){
  for(const locale of Array.isArray(locales)?locales:[locales]){
    const base=String(locale||'').toLowerCase().split('-')[0];
    if(LANGUAGES.some(item=>item.id===base))return base;
  }
  return 'en';
}
function getLanguage(){return language;}
function setLanguage(value){if(!LANGUAGES.some(l=>l.id===value))return false;language=value;return true;}
function languageTag(){return LANGUAGES.find(l=>l.id===language).tag;}
function translate(key,params={},locale=language){const index=LANGUAGES.findIndex(l=>l.id===locale);const row=MESSAGES[key];if(!row)return key;return row[index<0?0:index].replace(/\{(\w+)\}/g,(_,name)=>String(params[name]??`{${name}}`));}
const t=translate;
function number(value,digits=0){return new Intl.NumberFormat(languageTag(),{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(value);}
function familyText(id){return {name:t(`family.${id}.name`),short:t(`family.${id}.short`),desc:t(`family.${id}.desc`)};}

const TAU = Math.PI * 2;
const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
const lerp = (a,b,t) => a+(b-a)*t;
const dist = (a,b) => Math.hypot(a.x-b.x,a.y-b.y);
function rng(seed=71431) { return () => { seed|=0; seed=seed+0x6D2B79F5|0; let t=Math.imul(seed^seed>>>15,1|seed); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
class Hash {
  constructor(size=600){this.size=size;this.bins=new Map();}
  key(x,y){return `${Math.floor(x/this.size)},${Math.floor(y/this.size)}`;}
  add(o,pad=0){for(let x=Math.floor((o.x-pad)/this.size);x<=Math.floor((o.x+pad)/this.size);x++)for(let y=Math.floor((o.y-pad)/this.size);y<=Math.floor((o.y+pad)/this.size);y++){const k=`${x},${y}`;if(!this.bins.has(k))this.bins.set(k,[]);this.bins.get(k).push(o);}}
  near(x,y,r=0){const found=new Set();for(let ix=Math.floor((x-r)/this.size);ix<=Math.floor((x+r)/this.size);ix++)for(let iy=Math.floor((y-r)/this.size);iy<=Math.floor((y+r)/this.size);iy++)for(const o of this.bins.get(`${ix},${iy}`)||[])found.add(o);return [...found];}
}
