  const p=sim.player;
  for(const orb of sim.bonusOrbs){
    if(!orbVisible(orb,sim.time)||Math.abs(orb.x-view.x)>view.w/2+40||Math.abs(orb.y-view.y)>view.h/2+40)continue;
    const b=BONUS_TYPES.find(b=>b.id===orb.type),r=18+Math.sin(time*2+orb.id)*1.5;
    c.save();c.globalAlpha=Math.min(1,(sim.time-orb.readyAt)/.6,(orb.expiresAt-sim.time)/2);c.translate(orb.x,orb.y);c.beginPath();c.arc(0,0,r,0,TAU);c.fillStyle=b.color+'25';c.strokeStyle=b.color;c.lineWidth=1.5;c.shadowColor=b.color;c.shadowBlur=12;c.fill();c.stroke();c.shadowBlur=0;c.save();c.translate(-10,-10);c.scale(20/24,20/24);c.lineWidth=2;c.lineCap='round';c.lineJoin='round';for(const points of BONUS_ICONS[b.id]){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke();}c.restore();c.beginPath();c.arc(-7,-8,3,0,TAU);c.fillStyle='#ffffff80';c.fill();c.restore();
  }
  c.save();
  for(const b of BONUS_TYPES)if(bonusActive(p,b.id)){const i=BONUS_TYPES.indexOf(b);c.beginPath();c.arc(p.x,p.y,p.r+12+i*2,time+i,time+i+1.8);c.strokeStyle=b.color+'aa';c.lineWidth=2;c.stroke();}
  if(bonusActive(p,'magnet')||bonusActive(p,'frost')){c.beginPath();c.arc(p.x,p.y,bonusActive(p,'magnet')?260:230,0,TAU);c.strokeStyle='#aeeeff25';c.lineWidth=1;c.stroke();}
