  cx=870+Math.sin(time*.32)*175;cy=280+(k>3?Math.sin((k-3)/5*Math.PI)*150:0);body=[node(cx+20,cy,92),node(cx-85,cy-12,62)];
  for(const side of [-1,1])for(let i=0;i<4;i++){const knee={x:cx+(i-1.5)*130,y:cy+side*(170+i%2*30)},tip={x:cx+(i-1.5)*200,y:side<0?95:700};limb([point(cx+(i-1.5)*35,cy),knee,tip],11);}
