  if(p.id===3){ring({gap:cycle*1.7,duration:4});if(a.phase==='core')ring({gap:cycle*1.7+Math.PI,warn:2.9,duration:3});}
  if(p.id===4){ring({x:g.center.x,y:g.center.y+75,gap:Math.PI/2,gapSize:.5});ring({x:g.center.x,y:g.center.y+75,gap:-Math.PI/2,gapSize:.55,warn:3,duration:3.4});}
  if(p.id===5)beam(40,400,1400,400,{warn:2,duration:3,width:400,kind:'wake'});
  if(p.id===6){for(const [i,arm]of a.arms.entries())if(arm.hp>0||a.phase==='core'){const source=a.phase==='core'?g.mouth:arm,aim=Math.atan2(a.y-source.y,a.x-source.x)+(a.phase==='core'?(i-1)*.25:0);beam(source.x,source.y,source.x+Math.cos(aim)*1000,source.y+Math.sin(aim)*1000,{warn:1.3+i*.65,duration:.9,width:30});}}
  if(p.id===7){beam(200,80,1250,690,{warn:1.7,width:48,duration:.7});beam(1250,90,280,715,{warn:3.2,width:48,duration:.7});}
  if(p.id===8){beam(a.x,90,a.x,715,{kind:'web',warn:1.8,duration:3.6,width:15});beam(80,a.y,1370,a.y,{kind:'web',warn:2.7,duration:2.7,width:15});}
  if(p.id===9){for(let i=0;i<5;i++)add('pearl',{x:g.mouth.x,y:g.mouth.y,angle:Math.PI+(i-2)*.22,warn:2.1+i*.18,duration:.25});}
  if(p.id===10){beam(240,400,1300,400,{kind:'wake',warn:2,duration:3,width:500});if(a.phase==='core')ring({x:g.mouth.x,y:g.mouth.y,warn:3.5,duration:3,gapSize:.7});}
  if(p.id===11)for(const [i,arm]of a.arms.entries())if(arm.hp>0||a.phase==='core'){const source=a.phase==='core'?g.mouth:arm,angle=Math.atan2(a.y-source.y,a.x-source.x)+(a.phase==='core'?(i-3)*.18:i%2?.25:-.25);beam(source.x,source.y,source.x+Math.cos(angle)*1000,source.y+Math.sin(angle)*1000,{warn:1.6+i*.22,duration:.65,width:16});}
