function nestTarget(sim){
 const n=sim.nest,p=sim.player,site=nestSite(sim),closest=list=>list.sort((a,b)=>dist(a,p)-dist(b,p))[0];
 if(n.stage==='site')return closest([...sim.nestLayout.sites]);
 if(n.stage==='courtship')return nestPartner(sim);
 if(n.stage==='escort'&&nestPartner(sim)&&dist(p,nestPartner(sim))>350)return nestPartner(sim);
 if(n.stage==='build'||n.stage==='protect'){
  const needs=n.stage==='build'?['fiber','thread','shell']:['spine'];
  if(needs.some(k=>n.bag[k]>0))return site;
  return closest(sim.nestLayout.resources.filter(r=>needs.includes(r.kind)&&!n.collected.includes(r.id)&&(r.kind==='spine'?n.spines:n.built[r.kind])<NEST_MATERIALS[r.kind]));
 }
 return site;
}
function nestActionReady(sim){
 const n=sim.nest,p=sim.player,site=nestSite(sim),near=q=>q&&dist(p,q)<p.r+85&&sim.world.lineClear(p,q,3);
 if(sim.paused||!sim.started||sim.death||sim.birth)return false;
 if(n.stage==='site')return sim.nestLayout.sites.some(near);
 if(n.stage==='courtship')return progression(p.xp).level>=3&&n.trust>=3&&near(nestPartner(sim));
 if(!near(site))return false;
 if(n.stage==='build')return ['fiber','thread','shell'].some(k=>n.bag[k]>0&&n.built[k]<NEST_MATERIALS[k]);
 if(n.stage==='protect')return n.bag.spine>0;
 if(n.stage==='gestation')return n.gestation>=90;
 if(n.stage==='egg')return n.food>0&&n.fed<=1;
 if(n.stage==='hatchling')return true;
 return false;
}
function useNest(sim){
 if(!nestActionReady(sim))return false;const n=sim.nest,p=sim.player,previous=n.stage;
 if(n.stage==='site'){n.siteId=sim.nestLayout.sites.find(s=>dist(p,s)<p.r+85&&sim.world.lineClear(p,s,3)).id;n.stage='build';}
 else if(n.stage==='build'||n.stage==='protect'){
  for(const k of ['fiber','thread','shell']){const amount=Math.min(n.bag[k],NEST_MATERIALS[k]-n.built[k]);n.built[k]+=amount;n.bag[k]-=amount;}
  if(['fiber','thread','shell'].every(k=>n.built[k]===NEST_MATERIALS[k])){n.stage='protect';const amount=Math.min(n.bag.spine,10-n.spines);n.spines+=amount;n.bag.spine-=amount;}
  if(n.spines===10&&n.stage==='protect'){n.stage='courtship';findNestMate(sim);nestAward(sim,'home',400);}
 }
 else if(n.stage==='courtship'){n.stage='escort';n.trail=[{x:p.x,y:p.y}];sim.emit('nestLove','');}
 else if(n.stage==='gestation'){n.stage='egg';n.fed=0;nestAward(sim,'egg',500);}
 else if(n.stage==='egg'){n.food--;n.fed=60;}
 else if(n.stage==='hatchling'){n.stage='companion';nestAward(sim,'companion',1000);sim.emit('nestLove','');}
 sim.burst(p.x,p.y,'#d6eeb6',12);sim.emit('nestUpdate','nest.name.'+n.stage,previous===n.stage?(n.stage==='egg'?'nest.fed':'nest.delivered'):'nest.stage.'+n.stage);return true;
}
function updateNestMate(sim,dt){
 const n=sim.nest,p=sim.player,site=nestSite(sim);
 if(!['courtship','escort','bonding'].includes(n.stage))return;
 let mate=nestPartner(sim);
 if(!mate){mate=findNestMate(sim);if(!mate)return;if(n.stage!=='courtship'){n.trust=0;n.trail=[];storyStage(sim,'courtship');}}
 if(n.stage==='courtship'){
  if(dist(p,mate)<p.r+85&&sim.world.lineClear(p,mate,3)){const old=n.trust;n.trust=Math.min(3,n.trust+dt);if(old<3&&n.trust>=3)sim.emit('nestUpdate','nest.accept','nest.acceptHelp');}
 }else if(n.stage==='escort'){
  if(dist(p,mate)<100&&n.trail.length&&dist(n.trail.at(-1),p)>700)n.trail=[];
  const last=n.trail.at(-1)||mate;if(dist(last,p)>25&&dist(last,p)<300&&n.trail.length<1024)n.trail.push({x:p.x,y:p.y});
  while(n.trail.length&&dist(mate,n.trail[0])<18)n.trail.shift();
  const goal=n.trail[0]||p,d=dist(mate,goal);if(d>p.r+28||n.trail.length){const step=Math.min(d,dt*260);sim.world.moveCircle(mate,(goal.x-mate.x)/Math.max(d,1)*step,(goal.y-mate.y)/Math.max(d,1)*step,mate.r);mate.angle=Math.atan2(goal.y-mate.y,goal.x-mate.x);}
  if(dist(p,site)<100&&dist(mate,site)<115&&sim.world.lineClear(mate,site,3)){n.bonding=0;n.trail=[];storyStage(sim,'bonding');sim.emit('nestLove','');}
 }else{
  n.bonding=Math.min(6,n.bonding+dt);const angle=n.bonding*2.4;
  for(const [o,a] of [[p,angle],[mate,angle+Math.PI]]){const goal={x:site.x+Math.cos(a)*40,y:site.y+Math.sin(a)*30};if(o.player)sim.moveActor(o,(goal.x-o.x)*Math.min(1,dt*5),(goal.y-o.y)*Math.min(1,dt*5),dt);else sim.world.moveCircle(o,(goal.x-o.x)*Math.min(1,dt*5),(goal.y-o.y)*Math.min(1,dt*5),o.r);}
  if(n.bonding>=6){n.gestation=0;n.gestationCue=0;storyStage(sim,'gestation');sim.emit('nestLove','');}
 }
}
function updateNest(sim,dt){
 if(sim.paused||sim.death||sim.birth||!sim.started)return;
 const n=sim.nest,p=sim.player,site=nestSite(sim);sim.nestThreat=false;const stageBefore=n.stage;updateNestMate(sim,dt);
 if(n.stage!=='companion')for(const item of sim.nestLayout.resources){
  if(n.collected.includes(item.id))continue;const delivered=item.kind==='spine'?n.spines:n.built[item.kind];
  if(n.bag[item.kind]+delivered>=NEST_MATERIALS[item.kind])continue;
  if(dist(p,item)<p.r+13&&sim.world.lineClear(p,item,2)){n.collected.push(item.id);n.bag[item.kind]++;sim.burst(item.x,item.y,'#d8ecb1',8);}
 }
 if(site){
  for(const o of sim.actors){if(o.dead||o.behavior!=='hunter'||dist(o,site)>140||!sim.world.lineClear(o,site,2))continue;
   sim.nestThreat=true;const angle=Math.atan2(o.y-site.y,o.x-site.x);
   // Ten independently placed thorns leave an eastern entrance.
   const hit=Array.from({length:n.spines},(_,i)=>.55+i*(TAU-1.1)/9).some(a=>Math.abs(Math.atan2(Math.sin(a-angle),Math.cos(a-angle)))<.23);
   if(hit){o.stun=Math.max(o.stun||0,.35);const d=Math.max(1,dist(o,site));sim.moveActor(o,(o.x-site.x)/d*dt*100,(o.y-site.y)/d*dt*100);o.exposure=Math.min(.9,(o.exposure||0)+dt*.08);o.ignore=Math.max(o.ignore||0,1);}
  }
 }
 if(n.stage==='gestation'&&stageBefore==='gestation'){n.gestation=Math.min(90,n.gestation+dt);const cue=Math.floor(n.gestation/90*4);if(cue>n.gestationCue){n.gestationCue=cue;sim.emit('nestUpdate',cue===4?'nest.ready':'nest.name.gestation',cue===4?'nest.readyHelp':'nest.pregnancy',null,{percent:Math.floor(n.gestation/90*100)});}}
 if(n.stage==='egg'&&n.fed>0&&!sim.nestThreat){const growth=Math.min(dt,n.fed,180-n.incubation);n.incubation+=growth;n.fed-=growth;if(n.incubation>=180){storyStage(sim,'hatchling');sim.emit('nestLove','');}}
 updateCompanionCare(sim,dt);
 if(n.stage==='companion'&&companionReady(sim))updateNestCompanion(sim,dt);else if(n.stage==='companion'){const site=nestSite(sim)||sim.player;sim.nestCompanion={x:site.x,y:site.y-8,mode:'resting',rage:0};}
}
function updateNestCompanion(sim,dt){
 const p=sim.player,n=sim.nest,tuning=companionTuning(sim);sim.nestCompanion??={x:p.x,y:p.y,angle:0,cooldown:0,rage:0,injury:p.exposure||0,mode:'follow'};
 const b=sim.nestCompanion;b.angle+=dt*1.8;b.cooldown=Math.max(0,b.cooldown-dt);b.rage=Math.max(0,(b.rage||0)-dt);
 if(p.bitten>0||(p.exposure||0)>(b.injury||0)+.002){if(!b.rage)sim.emit('companionRage','nest.rage','nest.rageHelp');b.rage=3;}b.injury=p.exposure||0;
 const victim=sim.actors.filter(o=>!o.dead&&o.id!==n.mateId&&(o.behavior==='hunter'||o.feedTarget===p)&&dist(o,p)<560&&sim.world.lineClear(b,o,3)).sort((a,z)=>(z.feedTarget===p)-(a.feedTarget===p)||dist(a,p)-dist(z,p))[0];
 let desired={x:p.x+Math.cos(b.angle)*(p.r+38),y:p.y+Math.sin(b.angle)*(p.r+38)};b.mode='follow';
 if(victim){b.mode=b.rage?'rage':'defend';const d=Math.max(1,dist(victim,p));desired={x:p.x+(victim.x-p.x)/d*(p.r+55),y:p.y+(victim.y-p.y)/d*(p.r+55)};}
 else if(n.cargo>0||n.cargoItem){b.mode='return';desired=p;if(dist(b,p)<p.r+25){if(n.cargoItem){const item=n.cargoItem;n.cargoItem=null;sim.consumeSeed(p,item.family);sim.emit('companionPickup','');}if(n.cargo>0){const amount=n.cargo;n.cargo=0;sim.addBiomass(p,amount);sim.emit('companionMeal',sim.time>(b.mealNotice||0)?'nest.meal':'','nest.mealHelp',null,{amount});b.mealNotice=sim.time+8;}}}
 else{
  b.idle=p.movingInput?0:(b.idle||0)+dt;const radius=b.idle>.6?650:420;
  b.searchWait=Math.max(0,(b.searchWait||0)-dt);
  const available=q=>q&&(q.kind==='bonus'?orbVisible(q.item,sim.time):q.kind==='seed'? !q.item.used:!q.item.eaten)&&(q.kind!=='scrap'||sim.time>=(q.item.readyAt||0))&&dist(q.item,p)<=radius;
  if(!available(b.pick))b.pick=null;
  if(!b.pick&&b.searchWait===0){
   b.searchWait=.25;
   const candidates=[...sim.world.foodHash.near(p.x,p.y,radius).filter(f=>!f.eaten).map(item=>({kind:'food',item})),...sim.world.adaptationHash.near(p.x,p.y,radius).filter(f=>!f.used).map(item=>({kind:'seed',item})),...sim.scraps.filter(f=>!f.eaten&&sim.time>=(f.readyAt||0)).map(item=>({kind:'scrap',item})),...sim.bonusOrbs.filter(f=>orbVisible(f,sim.time)).map(item=>({kind:'bonus',item}))];
   b.pick=candidates.filter(available).sort((a,z)=>dist(a.item,b)-dist(z.item,b)).find(q=>sim.world.lineClear(b,q.item,12)&&sim.world.lineClear(p,q.item,12))||null;
  }
  const pick=b.pick;
  if(pick){const item=pick.item;b.mode='forage';desired=item;if(dist(b,item)<22){
   if(pick.kind==='bonus')collectBonus(sim,item);
   else if(pick.kind==='seed'){item.used=true;n.cargoItem={kind:'seed',family:item.family};}
   else if(pick.kind==='scrap'){item.count=(item.count||1)-1;item.eaten=item.count<=0;item.readyAt=sim.time+.18;if(item.kind==='seed')n.cargoItem={kind:'seed',family:item.family};else n.cargo=item.value;}
   else{item.eaten=true;item.gulp=0;item.respawn=sim.time+90;n.cargo=item.value*(bonusActive(p,'feast')?2:1);}
   b.pick=null;b.searchWait=0;sim.emit('companionPickup','');
  }}

 }
 if(dist(b,p)>700&&sim.world.lineClear(b,p,12))desired=p;
 const d=dist(b,desired),step=Math.min(d,dt*(b.rage?650:420)*(['forage','return'].includes(b.mode)?tuning.collection:1));if(d>1)sim.world.moveCircle(b,(desired.x-b.x)/d*step,(desired.y-b.y)/d*step,12);
 companionContact(sim,b);if(!companionReady(sim))return;
 // Recover after portals or respawn without abandoning carried food.
 if(dist(b,p)>1800){b.x=p.x;b.y=p.y;}
 if(victim&&b.cooldown===0){const d=Math.max(1,dist(b,victim));sim.nestShots.push({x:b.x,y:b.y,vx:(victim.x-b.x)/d*740,vy:(victim.y-b.y)/d*740,life:1.2,damage:(b.rage?.3:.2)*tuning.power,rage:!!b.rage});b.cooldown=(b.rage?.18:.42)/tuning.fireRate;sim.emit('companionShot','');}
 for(const shot of sim.nestShots){shot.life-=dt;const old={x:shot.x,y:shot.y},end={x:shot.x+shot.vx*dt,y:shot.y+shot.vy*dt};if(!sim.world.lineClear(old,end,3)){shot.life=0;continue;}shot.x=end.x;shot.y=end.y;
  const dx=end.x-old.x,dy=end.y-old.y,l2=dx*dx+dy*dy;
  const hit=sim.actors.find(o=>{if(o.dead||o.id===n.mateId||(o.behavior!=='hunter'&&o.feedTarget!==p))return false;const t=l2?clamp(((o.x-old.x)*dx+(o.y-old.y)*dy)/l2,0,1):0;return Math.hypot(o.x-old.x-t*dx,o.y-old.y-t*dy)<o.r+5&&sim.world.lineClear(old,o,2);});
  if(hit){shot.life=0;const damage=shot.damage||.2;hit.exposure=Math.min(1,(hit.exposure||0)+damage);hit.lastBitten=sim.time;hit.stun=Math.max(hit.stun||0,.7);hit.biteLedger??=new Map();hit.biteLedger.set(p,(hit.biteLedger.get(p)||0)+damage);sim.burst(shot.x,shot.y,shot.rage?'#ffc194':'#b9ffff',9);if(hit.exposure>=1)sim.finishAbsorption(hit);}
 }
 sim.nestShots=sim.nestShots.filter(s=>s.life>0);
}

const nestColors={fiber:'#9de5b8',thread:'#efc5ee',shell:'#ffdfae',spine:'#a9deff'};
function nestEllipse(c,x,y,rx,ry,angle=0){c.beginPath();c.ellipse(x,y,rx,ry,angle,0,TAU);}
function drawNestWorld(c,sim,time,view){
 if(!sim.started)return;const n=sim.nest,p=sim.player,site=nestSite(sim),visible=q=>!view||Math.abs(q.x-view.x)<view.w/2+180&&Math.abs(q.y-view.y)<view.h/2+180;c.save();
 if(n.stage==='site')for(const s of sim.nestLayout.sites){if(!visible(s))continue;c.setLineDash([6,7]);nestEllipse(c,s.x,s.y,73,58);c.strokeStyle='#e3d4a7aa';c.lineWidth=2;c.stroke();c.setLineDash([]);c.font='12px sans-serif';c.textAlign='center';c.fillStyle='#f4e5bb';c.fillText(t('nest.site'),s.x,s.y-85);}
 if(n.stage!=='companion')for(const item of sim.nestLayout.resources){if(!visible(item)||n.collected.includes(item.id))continue;const total=(item.kind==='spine'?n.spines:n.built[item.kind])+n.bag[item.kind];if(total>=NEST_MATERIALS[item.kind])continue;c.save();c.translate(item.x,item.y+Math.sin(time*1.6+item.x)*3);c.rotate(Math.sin(time*.6+item.y)*.2);c.strokeStyle=nestColors[item.kind];c.fillStyle=nestColors[item.kind]+'80';c.lineWidth=2;
 if(item.kind==='shell'){c.beginPath();c.moveTo(-10,8);c.quadraticCurveTo(-13,-10,0,-12);c.quadraticCurveTo(13,-8,11,8);c.closePath();c.fill();c.stroke();for(let i=-1;i<=1;i++){c.beginPath();c.moveTo(i*3,7);c.lineTo(i*7,-7);c.stroke();}}
 else if(item.kind==='spine'){c.beginPath();c.moveTo(0,-18);c.lineTo(5,10);c.lineTo(-4,10);c.closePath();c.fill();c.stroke();}
 else{for(let i=0;i<(item.kind==='fiber'?3:1);i++){c.beginPath();c.moveTo(-10,-8+i*5);c.bezierCurveTo(15,-20+i*5,-15,18+i*5,12,8+i*5);c.stroke();}}c.restore();if(dist(p,item)<155){c.font='10px sans-serif';c.textAlign='center';c.fillStyle=nestColors[item.kind];c.fillText(t('nest.material.'+item.kind),item.x,item.y+30);}}
 if(site&&visible(site)){
  c.save();c.translate(site.x,site.y);nestEllipse(c,0,0,64,48);c.fillStyle='#0c303aa8';c.fill();
  for(let i=0;i<n.built.fiber;i++){nestEllipse(c,Math.sin(i*2)*3,Math.cos(i)*3,42+i*2.4,27+i*1.7,i*.17);c.strokeStyle=i%2?'#94cba5':'#bdd9a1';c.lineWidth=2.8;c.stroke();}
  for(let i=0;i<n.built.thread;i++){c.beginPath();const a=i/6*TAU;c.moveTo(Math.cos(a)*58,Math.sin(a)*40);c.quadraticCurveTo(0,0,Math.cos(a+2)*58,Math.sin(a+2)*40);c.strokeStyle='#edcfe0b0';c.lineWidth=1.5;c.stroke();}
  for(let i=0;i<n.built.shell;i++){const a=1+i*1.45;nestEllipse(c,Math.cos(a)*58,Math.sin(a)*40,13,7,a);c.fillStyle='#e9d0ac';c.fill();c.strokeStyle='#fff1cf';c.stroke();}
  for(let i=0;i<n.spines;i++){const a=.55+i*(TAU-1.1)/9;c.save();c.rotate(a);c.beginPath();c.moveTo(65,-5);c.lineTo(103,0);c.lineTo(65,5);c.closePath();c.fillStyle='#99d4dc';c.fill();c.strokeStyle='#e3ffff';c.lineWidth=1.2;c.stroke();c.restore();}
  if(n.stage==='egg'){nestEllipse(c,0,-7,23,31);c.fillStyle=n.fed>0?'#e7e7baa0':'#bec5c880';c.fill();c.strokeStyle='#ffebc7';c.lineWidth=2;c.stroke();const growth=n.incubation/180;nestEllipse(c,Math.sin(time*1.6)*3,-5,5+growth*11,4+growth*8,time*.2);c.fillStyle='#aaf6e0';c.fill();c.beginPath();c.arc(0,-7,39,-Math.PI/2,-Math.PI/2+TAU*growth);c.strokeStyle='#a3f5d5';c.lineWidth=3;c.stroke();}
  c.restore();c.font='12px sans-serif';c.textAlign='center';c.fillStyle='#f3ddad';c.fillText(t('nest.home'),site.x,site.y+125);
 }
 const mate=nestPartner(sim);
 if(mate&&['courtship','escort','bonding'].includes(n.stage)&&visible(mate)){
  nestEllipse(c,mate.x,mate.y,mate.r+10,mate.r+7);c.strokeStyle='#ffc5e7';c.lineWidth=2;c.stroke();
  if(dist(p,mate)<p.r+110||n.stage!=='courtship')for(let i=0;i<4;i++){const phase=(time*.5+i*.25)%1;nestHeart(c,mate.x+Math.sin(i*2+time)*30,mate.y-mate.r-12-phase*42,5+phase*3,1-phase);}
 }
 if(n.stage==='bonding'&&site)for(let i=0;i<7;i++)nestHeart(c,site.x+Math.sin(time*2+i)*65,site.y+Math.cos(time*2+i)*48,7,.85);
 if(n.stage==='hatchling'&&site)drawNestBaby(c,{x:site.x+Math.sin(time*2)*16,y:site.y-8,angle:time},time);
 if(n.stage==='gestation'){nestEllipse(c,p.x+Math.cos(p.angle+1)*p.r*.5,p.y+Math.sin(p.angle+1)*p.r*.5,7+n.gestation/15,10+n.gestation/12,p.angle);c.fillStyle='#ffe7b87a';c.strokeStyle='#fff0c9';c.fill();c.stroke();}
 const b=sim.nestCompanion;if(n.stage==='companion'&&b)drawNestBaby(c,{...b,resting:n.companion?.recovery>0},time,sim.nest.cargo||sim.nest.cargoItem,n.companion);
 c.strokeStyle='#b9ffff';c.lineWidth=3;for(const shot of sim.nestShots){c.strokeStyle=shot.rage?'#ffb080':'#b9ffff';c.lineWidth=shot.rage?5:3;c.beginPath();c.moveTo(shot.x,shot.y);c.lineTo(shot.x-shot.vx*.045,shot.y-shot.vy*.045);c.stroke();}c.restore();
}
function drawNestMap(c,sim,scale,full=false){
 if(!sim.started)return;const n=sim.nest,site=nestSite(sim),target=nestTarget(sim);c.save();c.lineWidth=1.5/scale;
 if(full){const route=nestRoute(sim);if(route.length){c.beginPath();c.moveTo(route[0].x,route[0].y);for(const q of route.slice(1))c.lineTo(q.x,q.y);c.strokeStyle='#ffc3e0';c.lineWidth=3/scale;c.setLineDash([9/scale,6/scale]);c.stroke();c.setLineDash([]);}}
 const mark=(q,color)=>{c.beginPath();c.moveTo(q.x,q.y-6/scale);c.lineTo(q.x+6/scale,q.y);c.lineTo(q.x,q.y+6/scale);c.lineTo(q.x-6/scale,q.y);c.closePath();c.fillStyle=color;c.fill();c.strokeStyle='#fff6db';c.stroke();};
 if(n.stage==='site')for(const candidate of sim.nestLayout.sites)mark(candidate,'#d7c692');else if(site)mark(site,'#e1b978');
 for(const item of nestMapResources(sim)){
  c.save();c.translate(item.x,item.y);c.scale(1/scale,1/scale);c.beginPath();
  if(item.kind==='spine'){c.moveTo(0,-14);c.lineTo(8,9);c.lineTo(-8,9);c.closePath();}
  else if(item.kind==='shell'){c.rect(-9,-9,18,18);}
  else if(item.kind==='fiber'){c.arc(0,0,9,0,TAU);}
  else{c.moveTo(-11,-4);c.lineTo(-4,-4);c.lineTo(-4,-11);c.lineTo(4,-11);c.lineTo(4,-4);c.lineTo(11,-4);c.lineTo(11,4);c.lineTo(4,4);c.lineTo(4,11);c.lineTo(-4,11);c.lineTo(-4,4);c.lineTo(-11,4);c.closePath();}
  c.fillStyle=nestColors[item.kind];c.fill();c.strokeStyle='#071c39';c.lineWidth=2;c.stroke();c.restore();
 }

 if(full&&n.stage==='escort'){const mate=nestPartner(sim);if(mate&&mate!==target)nestHeart(c,mate.x,mate.y,8/scale);}
 if(target){c.beginPath();c.arc(target.x,target.y,12/scale,0,TAU);c.strokeStyle='#baffda';c.stroke();if(full&&['courtship','escort'].includes(n.stage)){if(nestDestinationKey(sim)==='nest.map.partner')nestHeart(c,target.x,target.y,8/scale);c.font=`bold ${20/scale}px sans-serif`;c.textAlign=target.x<sim.player.x?'left':'right';c.lineWidth=5/scale;c.strokeStyle='#071c39';const lx=target.x+(target.x<sim.player.x?20:-20)/scale,ly=target.y+(target.y<sim.player.y?32:-23)/scale;const label=t(nestDestinationKey(sim)==='nest.map.partner'?'nest.map.partner':'nest.home');c.strokeText(label,lx,ly);c.fillStyle='#ffe3ef';c.fillText(label,lx,ly);}}

 c.restore();
}

