 if(look.tail>0){const length=12+look.tail*.38;c.beginPath();c.moveTo(-17,4);c.bezierCurveTo(-28,15,-25-length*.6,Math.sin(time*4)*17,-22-length,Math.sin(time*4+1)*14);c.stroke();}
