 // Soft external gills and jellyfish ribbons belong to these body silhouettes.
 if(shape==='jelly')for(let i=-1;i<=1;i++){const x=i*10,wave=Math.sin(time*3+i)*3;c.beginPath();c.moveTo(x-2,7);c.bezierCurveTo(x-6,17,x+wave-4,22,x+wave,26-Math.abs(i)*3);c.bezierCurveTo(x+wave+4,21,x+3,16,x+2,7);c.fillStyle=color+'9c';c.fill();c.strokeStyle='#d3ffffb0';c.lineWidth=1;c.stroke();}
 if(shape==='axolotl')for(const side of [-1,1])for(let i=0;i<3;i++){const y=-11+i*8;c.beginPath();c.moveTo(side*13,y+3);c.quadraticCurveTo(side*22,y-9,side*(27-Math.abs(i-1)*2),y-6+Math.sin(time*3+i));c.quadraticCurveTo(side*26,y+2,side*13,y+6);c.fillStyle=color+'a8';c.fill();c.strokeStyle='#d3ffffb0';c.lineWidth=1;c.stroke();}
 c.beginPath();
 if(shape==='bubble')c.ellipse(0,0,19,17,0,0,TAU);
 else if(shape==='drop'){c.moveTo(0,-23);c.bezierCurveTo(9,-10,24,3,14,13);c.bezierCurveTo(4,24,-21,14,-17,2);c.quadraticCurveTo(-12,-9,0,-23);}
