    while(budget>0){const value=Math.min(budget,[1,2,1,3][i%4]);items.push({kind:'nutrient',value,r:4+value,life:90,color:FOOD_COLORS[i%FOOD_COLORS.length],shape:i%3});budget-=value;i++;}
