      const item=items[j],angle=j/Math.max(1,items.length)*TAU+this.random()*.18,speed=90+this.random()*95,drop={...item,x:victim.x,y:victim.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,readyAt:this.time+.55,eaten:false};
