  respawn(){this.boostCharges=3;this.boost=0;this.escapeDash=0;this.escapeGuard=0;this.boostDuration=0;const p=this.player;this.death=null;p.deathAlpha=0;p.birthAlpha=0;p.hidden=false;p.coverage=0;p.stillTime=0;p.rustle=0;const room=this.world.rooms[this.checkpoint];p.biomass=Math.floor(p.biomass*.78);p.r=playerRadius(p);p.x=room.x;p.y=room.y;p.vx=p.vy=0;p.exposure=0;p.bitten=0;p.attackers=0;p.biteLedger=new Map();p.shedCount=0;p.feedTarget=null;if(p.foodTarget)p.foodTarget.gulp=0;p.foodTarget=null;this.nutrientFeeding=null;this.recentMeal=null;p.compression=0;p.tail=[];p.stun=4;this.applyGrowth(p);this.capture=0;this.stats.captures++;this.camera.x=p.x;this.camera.y=p.y;this.birth={duration:1.55,remaining:1.55};for(const a of this.actors)if(dist(a,p)<400){a.ignore=8;a.target=this.world.pointIn(room,.8);a.decision=2;}this.emit('return','event.returnTitle','event.returnBody');this.celebrate(p,'#d5edc0',1.5);}
