  g.arms.forEach((v,i)=>{if(a.arms[i].hp<=0)return;const side=i?1:-1;c.save();c.translate(v.x,v.y);c.rotate(side*(k<3?.3:-.25));for(const claw of [-1,1]){const bite=k>1.7&&k<3?.15:.55;c.save();c.rotate(claw*bite);guardianShellSurface(c,[{x:-43,y:-28},{x:20,y:-55},{x:75,y:-30},{x:94,y:15},{x:43,y:-8},{x:8,y:17},{x:-32,y:24}],color);c.restore();}c.restore();});
