  const membrane=c.createLinearGradient(0,y-150,0,y+85);membrane.addColorStop(0,'#e1fff3c0');membrane.addColorStop(.28,color+'59');membrane.addColorStop(.8,'#6587c532');membrane.addColorStop(1,color+'cc');c.fillStyle=membrane;c.fill();c.strokeStyle='#c5fff3bd';c.lineWidth=2;c.stroke();
  for(let i=-3;i<=3;i++){c.beginPath();c.moveTo(x,y-100);c.bezierCurveTo(x+i*28,y-75,x+i*61,y+25,x+i*60,y+67);c.strokeStyle='#dff9f07a';c.lineWidth=1.3;c.stroke();guardianCell(c,x+i*45,y+15,18,39,color,i,a.time);}guardianHeart(c,x,y-30,35,'#f5cedd',a.time);
