let keys=new Set(),pointer={x:innerWidth/2,y:innerHeight/2,active:false},boostQueued=false,survivalQueued=false,last=performance.now(),accumulator=0,uiTimer=0,feedingTimer=0,toastUntil=0,toastQueue=[],activeToast=null,currentModal=null,hasSave=false,loadFailed=false,saveWarningShown=false,lives=[],activeLifeId=null,slowFrames=0;
try{setLanguage(localStorage.getItem('nacar.language')||preferredLanguage(navigator.languages?.length?navigator.languages:[navigator.language]));}catch{setLanguage(preferredLanguage(navigator.languages?.length?navigator.languages:[navigator.language]));}
