try{
  try{lives=await durable.load();}catch{loadFailed=true;throw new Error("save could not be read");}let selected=await durable.selected();if(!selected)try{selected=gameStorage.getItem(ACTIVE_SLOT_KEY);}catch{}activeLifeId=lives.find(l=>l.id===selected)?.id||lives[0]?.id||null;const active=lives.find(l=>l.id===activeLifeId);if(active?.data){try{if(!sim.restore(active.data))throw new Error('invalid saved game');hasSave=true;sim.savedAt=active.updatedAt;sound.setPosition(active.data.musicStep);}catch(e){loadFailed=true;throw e;}}
  saveLoaded=true;
  const music=localStorage.getItem('nacar.music');if(music!==null){sound.setMusicVolume(Number(music));$('#music-volume').value=Number(music)*100;}
  const vol=localStorage.getItem('nacar.volume');if(vol!==null){sound.setVolume(Number(vol));$('#volume').value=Number(vol)*100;}const quality=localStorage.getItem('nacar.quality'),mobile=matchMedia('(pointer:coarse)').matches&&Math.min(innerWidth,innerHeight)<900;const selectedQuality=quality||(mobile?'light':'balanced');renderer.setQuality(selectedQuality);$('#quality').value=selectedQuality;
}catch{sim.saveAvailable=false;if(!saveLoaded)loadFailed=true;}
sound.setTimbre(sim.player.metamorphosis.loadout.song);
function applyLanguage(){
  document.documentElement.lang=languageTag();document.title=t('page.title');$('meta[name="description"]').content=t('page.description');
  for(const element of document.querySelectorAll('[data-i18n]'))element.innerHTML=t(element.dataset.i18n);
  for(const element of document.querySelectorAll('[data-i18n-aria]'))element.setAttribute('aria-label',t(element.dataset.i18nAria));
  for(const element of document.querySelectorAll('[data-i18n-title]'))element.title=t(element.dataset.i18nTitle);
  for(const select of document.querySelectorAll('[data-language]')){select.innerHTML=LANGUAGES.map(l=>`<option value="${l.id}" lang="${l.tag}">${l.name}</option>`).join('');select.value=getLanguage();}
  $('#start-btn').disabled=loadFailed;$('#restore-file').disabled=loadFailed||lives.length>=MAX_LIVES;$('#backup-welcome').disabled=!activeLifeId;$('#backup-previous').disabled=!activeLifeId;
  $('#start-btn').innerHTML=`${t(hasSave?'welcome.continue':'welcome.start')} <span>↗</span>`;
  $('#save-note').textContent=loadFailed?t('notice.saveTitle'):hasSave?t('welcome.saved',{percent:number(world.exploration,1)}):t('welcome.note');renderDifficulty();renderLives();
  updateVolumeLabels();updateTrackLabels();hud();if(currentModal)renderModal(currentModal);if(activeToast)renderToast(activeToast);
}
function changeLanguage(event){
  if(!setLanguage(event.target.value))return;keys.clear();pointer.active=false;boostQueued=false;survivalQueued=false;
  try{localStorage.setItem('nacar.language',getLanguage());}catch{}
  applyLanguage();
}
for(const select of document.querySelectorAll('[data-language]')){select.addEventListener('change',changeLanguage);select.addEventListener('pointerdown',()=>{keys.clear();pointer.active=false;});}
function persistLife(data){
  const task=async()=>{if(!activeLifeId||loadFailed)throw new Error('no active life');const previous=lives.find(l=>l.id===activeLifeId);lives=await durable.write(lives,{id:activeLifeId,createdAt:previous?.createdAt||Date.now(),updatedAt:Date.now(),data});};
  const pending=saveChain.then(task);saveChain=pending.catch(()=>{});return pending;
}
async function save(){
  if(!sim.started||loadFailed)return;
  savingCount++;renderSaveStatus();
  try{const data=structuredClone({...sim.serialize(),musicStep:sound.musicStep});await persistLife(data);sim.savedAt=lives.find(l=>l.id===activeLifeId).updatedAt;sim.saveAvailable=true;saveWarningShown=false;}
  catch{sim.saveAvailable=false;if(!saveWarningShown){saveWarningShown=true;toastQueue.push({type:'notice',title:'notice.saveTitle',body:'notice.saveBody'});}}
  finally{savingCount--;renderSaveStatus();}
}
function renderSaveStatus(){const status=$('#save-status');status.textContent=t(savingCount?'save.pending':!sim.saveAvailable?'save.failed':sim.savedAt?'save.confirmed':'save.waiting',{time:new Date(sim.savedAt).toLocaleTimeString(languageTag())});status.classList.toggle('failed',!sim.saveAvailable);status.title=sim.saveAvailable?'':t('notice.saveBody');const paused=$('.saved-info');if(paused){paused.textContent=status.textContent+' · '+t('pause.stats',{minutes:number(Math.floor(sim.time/60)),percent:number(world.exploration,1)});paused.classList.toggle('failed',!sim.saveAvailable&&!savingCount);}const retry=$('#pause-save');if(retry)retry.disabled=!!savingCount;const bossStatus=$('#boss-save');if(bossStatus)bossStatus.textContent=status.textContent;}
function downloadGame(data,name='partida'){const blob=new Blob([JSON.stringify({format:'nacar-backup-v1',data})],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`nacar-${name}-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCurrent(){if(sim.started)downloadGame(sim.serialize());else{const life=lives.find(l=>l.id===activeLifeId);if(life?.data)downloadGame(life.data);}}
$('#backup-live').onclick=exportCurrent;$('#backup-welcome').onclick=exportCurrent;
$('#backup-previous').onclick=async()=>{try{const previous=await durable.previous(activeLifeId);if(!previous?.data){alert(t('save.noPrevious'));return;}downloadGame(previous.data,'copia-anterior');}catch{alert(t('notice.saveBody'));}};
$('#restore-file').onchange=async e=>{
  const file=e.target.files[0];if(!file)return;
  try{if(file.size>25000000)throw new Error('large backup');const backup=JSON.parse(await file.text());if(backup.format!=='nacar-backup-v1')throw new Error('invalid backup');const validation=new Simulation(new World());if(!validation.restore(backup.data))throw new Error('invalid backup');
    if(loadFailed||lives.length>=MAX_LIVES)throw new Error('life unavailable');
    const life=newLife(backup.data);lives=await durable.write(lives,life);await durable.select(life.id);location.reload();
  }catch{alert(t('save.importFailed'));}finally{e.target.value='';}
};
function renderLives(){const holder=$('#save-slots');if(!holder)return;holder.innerHTML=lives.map((life,index)=>{const q=lifeSummary(life),active=life.id===activeLifeId;return `<article class="life-slot${active?' selected':''}"><button class="life-select" data-life="${life.id}"><b>${t('save.life',{number:number(index+1)})}</b><small>${t('save.summary',{mass:number(q.biomass),minutes:number(q.minutes)})}</small></button><button class="life-remove" data-remove-life="${life.id}" aria-label="${t('save.remove')}">×</button></article>`;}).join('');for(const button of holder.querySelectorAll('[data-life]'))button.onclick=async()=>{try{await durable.select(button.dataset.life);location.reload();}catch{alert(t('notice.saveBody'));}};for(const button of holder.querySelectorAll('[data-remove-life]'))button.onclick=async()=>{if(!confirm(t('save.confirmDelete')))return;try{lives=await durable.remove(lives,button.dataset.removeLife);}catch{alert(t("notice.saveBody"));return;}if(button.dataset.removeLife===activeLifeId){location.reload();return;}renderLives();applyLanguage();};const fresh=$('#new-life');fresh.disabled=loadFailed||lives.length>=MAX_LIVES;fresh.textContent=t(lives.length>=MAX_LIVES?'save.full':'save.new');fresh.onclick=async()=>{if(loadFailed||lives.length>=MAX_LIVES)return;const life=newLife(null);try{lives=await durable.write(lives,life);}catch{alert(t("notice.saveBody"));return;}await durable.select(life.id);location.reload();};}
function renderDifficulty(){const holder=$('#difficulty-options');if(!holder)return;for(const button of holder.querySelectorAll('[data-difficulty]')){const level=button.dataset.difficulty;button.classList.toggle('selected',level===sim.difficulty);button.innerHTML=`<b>${t(`difficulty.${level}`)}</b><small>${t(`difficulty.${level}Copy`)}</small>`;}$('#difficulty-copy').textContent=t('difficulty.note');}
for(const button of document.querySelectorAll('[data-difficulty]'))button.onclick=()=>{if(!sim.setDifficulty(button.dataset.difficulty))return;renderDifficulty();if(hasSave){persistLife(structuredClone({...sim.serialize(),musicStep:sound.musicStep})).catch(()=>{sim.saveAvailable=false;renderSaveStatus();});}};

function start(){if(loadFailed)return;if(!activeLifeId){const life=newLife(null);activeLifeId=life.id;durable.select(life.id).catch(()=>{});}navigator.storage?.persist?.().catch(()=>{});sim.started=true;sim.paused=false;document.body.classList.add('playing');$('#welcome').classList.add('leaving');setTimeout(()=>$('#welcome').hidden=true,650);$('#hud').hidden=false;pointer.active=false;sound.start();$('#world').focus({preventScroll:true});if(!hasSave)sim.emit('birth','event.birthTitle','event.birthBody');save();}
function openPortals(){if(!sim.started||world.discoveredRegions.size<2){toastQueue.push({type:'notice',title:'notice.portalTitle',body:'notice.portalBody'});return;}openModal('portals');}
$('#start-btn').addEventListener('click',start);
$('#boss-action').onclick=()=>{if(bossInteract(sim)){save();hud();}};
$('#boss-backup').onclick=exportCurrent;
let mouseShooting=false;
$('#world').addEventListener('pointerdown',e=>{if(sim.boss.active&&e.button===0){mouseShooting=true;pointer={x:e.clientX,y:e.clientY,active:true};}});
window.addEventListener('pointerup',()=>mouseShooting=false);
window.addEventListener('blur',()=>mouseShooting=false);
$('#nest-action').onclick=()=>{if(useNest(sim)){save();hud();}};
$('#mission-tracker').onclick=$('#missions-btn').onclick=()=>openModal('missions');
$('#release-btn').onclick=()=>{$('#settings-menu').hidden=true;$('#settings-btn').setAttribute('aria-expanded','false');openModal('releases');};
$('#settings-btn').onclick=()=>{const menu=$('#settings-menu');menu.hidden=!menu.hidden;$('#settings-btn').setAttribute('aria-expanded',String(!menu.hidden));pointer.active=false;};
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#settings-menu')&&!e.target.closest('#settings-btn')){$('#settings-menu').hidden=true;$('#settings-btn').setAttribute('aria-expanded','false');}});
$('#survival-button').onclick=()=>{if(sim.started&&!currentModal)survivalQueued=true;};
$('#world').addEventListener('pointermove',e=>{pointer={x:e.clientX,y:e.clientY,active:true};});
$('#world').addEventListener('pointerleave',()=>pointer.active=false);
window.addEventListener('keydown',e=>{
  if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;
  if(e.target instanceof HTMLButtonElement&&[' ','Enter'].includes(e.key))return;
  const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','escape','m','p','e','b','c','q','j','f','z','w','a','s','d'].includes(key))e.preventDefault();if(e.repeat)return;
  if(key==='escape'){if(currentModal)closeModal();else if(sim.started)openModal('pause');return;}
  if(key==='j'){if(sim.started)currentModal==='missions'?closeModal():openModal('missions');return;}
  if(key==='m'){if(sim.started)currentModal==='atlas'?closeModal():openModal('atlas');return;}
  if(key==='p'){if(currentModal==='portals')closeModal();else openPortals();return;}
  if(key==='e'){if(sim.started)currentModal==='journal'?closeModal():openModal('journal');return;}
  if(key==='b'||key==='c'){if(sim.started)(currentModal==='metamorphosis'||currentModal==='bag')?closeModal():openModal('metamorphosis');return;}
  if(currentModal)return;
  if(key==='f'&&sim.started){if(sim.boss.active||nearbyBossGate(sim)){if(bossInteract(sim)){save();hud();}return;}if(useNest(sim)){save();hud();}return;}
  if(key==='q'&&sim.started)survivalQueued=true;if(key===' ')boostQueued=true;keys.add(key);
});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
window.addEventListener('resize',()=>{renderer.resize();if(currentModal==='atlas')drawAtlas();});
window.addEventListener('blur',()=>{keys.clear();pointer.active=false;boostQueued=false;survivalQueued=false;controller.reset();if(sim.started&&!currentModal)openModal('pause');save();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(sim.started&&!currentModal)openModal('pause');save();}});
window.addEventListener('pagehide',save);
window.addEventListener('beforeunload',e=>{if(sim.started&&(!sim.saveAvailable||savingCount)){e.preventDefault();e.returnValue='';}});
$('#atlas-btn').onclick=()=>{if(sim.started)openModal('atlas');else toastQueue.push({type:'notice',title:'notice.atlasTitle',body:'notice.atlasBody'});};$('#portal-btn').onclick=openPortals;$('#help-btn').onclick=()=>openModal('help');
$('#mini-btn').onclick=()=>openModal('atlas');$('#journal-btn').onclick=()=>openModal('journal');$('#pause-btn').onclick=()=>sim.started?openModal('pause'):null;$('#close-overlay').onclick=closeModal;
$('#bag-btn').onclick=$('#metamorph-btn').onclick=()=>openModal('metamorphosis');
$('.brand').onclick=e=>{e.preventDefault();if(sim.started)openModal('pause');};
$('#overlay').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
function updateVolumeLabels(){$('#volume-label').textContent=number(sound.volume*100)+'%';$('#music-label').textContent=number(sound.musicVolume*100)+'%';}
function updateTrackLabels(){
  const track=sound.currentTrack;$('#track-name').textContent=track?track.title:t('sound.ready');$('#track-composer').textContent=track?track.composer:t('sound.selection');
  $('#playlist-size').textContent=t('sound.library',{count:number(SCORE_LIBRARY.length)});$('#next-track').disabled=!track;$('#music-credits').disabled=!sim.started;
}
sound.onTrackChange=()=>{updateTrackLabels();try{localStorage.setItem('nacar.playlist.v1',JSON.stringify(sound.playlistState()));}catch{}};
$('#next-track').onclick=()=>{sound.nextTrack();pointer.active=false;};
$('#music-credits').onclick=()=>{if(sim.started)openModal('music');};
$('#sound-btn').onclick=()=>{$('#sound-popover').hidden=!$('#sound-popover').hidden;$('#quality-popover').hidden=true;pointer.active=false;};$('#quality-btn').onclick=()=>{$('#quality-popover').hidden=!$('#quality-popover').hidden;$('#sound-popover').hidden=true;pointer.active=false;};$('#quality').onchange=e=>{renderer.setQuality(e.target.value);try{localStorage.setItem('nacar.quality',e.target.value);}catch{}};
$('#volume').oninput=e=>{sound.setVolume(Number(e.target.value)/100);updateVolumeLabels();try{localStorage.setItem('nacar.volume',String(sound.volume));}catch{}};
$('#music-volume').oninput=e=>{sound.setMusicVolume(Number(e.target.value)/100);updateVolumeLabels();try{localStorage.setItem('nacar.music',String(sound.musicVolume));}catch{}};
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#sound-popover')&&!e.target.closest('#sound-btn')&&!e.target.closest('#quality-btn')&&!e.target.closest('#quality-popover')){$('#sound-popover').hidden=true;$('#quality-popover').hidden=true};});
function openModal(kind){if(sim.boss.active&&!['pause','help','reset','releases'].includes(kind))return;if(!sim.started&&!['help','releases'].includes(kind))return;if(sim.started)save();sim.paused=true;sound.pause(true);keys.clear();boostQueued=false;survivalQueued=false;pointer.active=false;currentModal=kind;if(kind==='metamorphosis'||kind==='bag')metamorph.begin(kind==='bag');renderModal(kind);if(!$('#overlay').open)$('#overlay').showModal();}
function renderModal(kind){
  const el=$('#overlay-content');
  $('#overlay').classList.toggle('release-dialog',kind==='releases');
  if(kind==='releases')$('#overlay').scrollTop=0;
  $('#overlay').classList.toggle('missions-dialog',kind==='missions');
  $('#overlay').classList.toggle('metamorph-dialog',kind==='metamorphosis'||kind==='bag');
  if(kind==='metamorphosis'||kind==='bag'){metamorph.render(el);return;}
  if(kind==='missions'){el.innerHTML=missionsScreen();$('#quests-play').onclick=closeModal;return;}
  if(kind==='releases'){el.innerHTML=releaseScreen();$('#release-close').onclick=closeModal;return;}
  if(kind==='help'){
    const sections=['move','food','pending','seeds','safety','bonuses','hazards','survival','mission','nest'];
    el.innerHTML=`<span class="modal-eyebrow">${t('manual.kicker')}</span><h2 class="modal-title">${t('manual.title')}</h2><p class="modal-copy">${t('manual.copy')}</p><div class="manual-grid">${sections.map(section=>`<article class="manual-card"><h3>${t(`manual.${section}Title`)}</h3><p>${t(`manual.${section}Body`)}</p></article>`).join('')}</div>`;
  }
  if(kind==='help')el.innerHTML+=`<div class="manual-grid">${BONUS_TYPES.map(b=>`<article class="manual-card"><h3>${bonusIcon(b.id)} ${t('bonus.'+b.id)}</h3><p>${t('bonus.'+b.id+'Help')}</p></article>`).join('')}</div>`;
  if(kind==='help'){
    const groups={plant:'shot',bait:'contact',anemone:'trap',urchin:'contact',jelly:'pulse',leech:'trap',spores:'cloud',mine:'pulse',current:'pull',frost:'slow',coral:'contact',worm:'giant',siphon:'pull',mimic:'contact',eel:'pulse',ink:'slow',reeds:'contact',web:'trap',acid:'cloud',echo:'call'};
    el.innerHTML+=`<h3>${t('manual.hazardsTitle')}</h3><div class="manual-grid">${HAZARD_KINDS.map(k=>`<article class="manual-card"><h3>${t('hazard.name.'+k)}</h3><p>${t('hazard.help.'+groups[k])}</p></article>`).join('')}</div>`;
  }
  if(kind==='music'){
    const escape=text=>String(text).replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));
    el.innerHTML=`<span class="modal-eyebrow">${t('sound.selection')}</span><h2 class="modal-title">${t('sound.credits')}</h2><p class="modal-copy">${t('sound.creditCopy')}</p><div class="music-credits-list">${SCORE_LIBRARY.map(track=>`<article><b>${escape(track.composer)}</b><a href="${track.source}" target="_blank" rel="noopener">${escape(track.title)}</a><small>${escape(track.credit)} · <a href="${track.licenseUrl}" target="_blank" rel="noopener">${escape(track.license)}</a></small></article>`).join('')}</div>`;
  }
  if(kind==='pause'){
    el.innerHTML=`<span class="modal-eyebrow">${t('pause.kicker')}</span><h2 class="modal-title">${t('pause.title')}</h2><p class="modal-copy">${t('pause.copy')}</p><div class="controls-grid"><kbd>${t('control.mouse')}</kbd><span>${t('control.mouseHelp')}</span><kbd>W A S D</kbd><span>${t('control.keysHelp')}</span><kbd>${t('control.space')}</kbd><span>${t('control.boostHelp')}</span><kbd>🎮</kbd><span>${t('control.controllerHelp')}</span><kbd>M / E</kbd><span>${t('control.mapHelp')}</span><kbd>ESC</kbd><span>${t('control.pauseHelp')}</span></div><div class="pause-actions"><button class="primary" id="resume">${t('pause.continue')} <span>↗</span></button><button class="secondary" id="pause-releases">${t('release.title')}</button><button class="secondary" id="pause-journal">${t('pause.organism')}</button><button class="secondary" id="reset">${t('pause.new')}</button><button class="secondary" id="pause-backup">${t('save.export')}</button><button class="secondary" id="pause-save">${t('save.retry')}</button></div><small class="saved-info" role="status" aria-live="polite">${t('save.pending')} · ${t('pause.stats',{minutes:number(Math.floor(sim.time/60)),percent:number(world.exploration,1)})}</small>`;
    $('#pause-backup').onclick=exportCurrent;$('#pause-save').onclick=save;renderSaveStatus();
    $('#pause-releases').onclick=()=>openModal('releases');
    $('#resume').onclick=closeModal;$('#pause-journal').onclick=()=>openModal('journal');$('#reset').onclick=()=>{currentModal='reset';renderModal('reset');};
  }
  if(kind==='atlas'){
    el.innerHTML=`<span class="modal-eyebrow">${t('atlas.kicker')}</span><h2 class="modal-title">${t('atlas.title')}</h2><p class="modal-copy">${t('atlas.stats',{percent:number(world.exploration,1),regions:number(world.discoveredRegions.size),memories:number(world.visitedLandmarks.size)})}</p>${['courtship','escort'].includes(sim.nest.stage)?`<section class="nest-route-help"><strong>${t('nest.name.'+sim.nest.stage)}</strong><p>${t('nest.map.routeHelp')}</p><p>${nestDescription()}</p><b>${nestProgressText()}</b></section>`:''}<canvas id="atlas-map" class="atlas-map" width="1440" height="760" aria-label="${t('atlas.label')}"></canvas><div class="atlas-legend"><span><i></i>${t('atlas.you')}</span><span><i></i>${t('atlas.memories')}</span><span><i style="background:#a3d4cf"></i>${t('atlas.refuges')}</span><span><i class="nest-map-home"></i>${t('nest.home')}</span><span><i class="nest-map-target"></i>${t(nestDestinationKey(sim))}</span>${nestMaterialNeeds(sim).filter(n=>n.missing>0).map(n=>`<span><i class="nest-map-${n.kind}"></i>${t('nest.material.'+n.kind)}</span>`).join('')}</div>${nestMaterialNeeds(sim).length?`<div class="nest-map-needs">${nestMaterialNeeds(sim).map(n=>`<div><b><i class="nest-map-${n.kind}"></i>${t('nest.material.'+n.kind)}</b><span>${t('nest.map.remaining',{missing:number(n.missing),bag:number(n.bag),collect:number(n.collect)})}</span></div>`).join('')}</div><p class="nest-map-help">${t('nest.map.materialHelp')}</p>`:''}`;drawAtlas();
  }
  if(kind==='portals'){
    const destinations=[...world.discoveredRegions].sort((a,b)=>a-b);
    el.innerHTML=`<span class="modal-eyebrow">${t('portal.kicker')}</span><h2 class="modal-title">${t('portal.title')}</h2><p class="modal-copy">${t('portal.copy')}</p><div class="portal-grid">${destinations.map(biome=>`<button class="portal-choice" data-portal="${biome}" style="--portal:${BIOMES[biome].map}"><i></i><span><b>${t(`biome.${biome}.name`)}</b><small>${t(`biome.${biome}.sub`)}</small></span><em>↗</em></button>`).join('')}</div>`;
    for(const button of el.querySelectorAll('[data-portal]'))button.onclick=()=>{if(sim.travelPortal(Number(button.dataset.portal)))closeModal();};
  }
  if(kind==='journal'){
    const known=FAMILIES.filter(f=>sim.player.acquired[f.id]);
    el.innerHTML=`<span class="modal-eyebrow">${t('journal.kicker')}</span><h2 class="modal-title">${t('journal.title')}</h2><p class="modal-copy">${t('journal.copy')}</p><div class="journal-grid">${known.map(f=>{const text=familyText(f.id);return`<article class="journal-card"><canvas width="130" height="150" data-part="${f.id}" aria-label="${text.name}"></canvas><div><h3>${text.name}</h3><p>${text.desc}</p><small>${t('journal.level',{trait:text.short,level:number(sim.player.acquired[f.id])})}${sim.player.parts[f.id]!==sim.player.acquired[f.id]?' · '+t('journal.pending'):''}</small></div></article>`;}).join('')}</div><p class="journal-empty">${known.length?t('journal.summary',{count:number(known.length)}):t('journal.empty')}</p>`;
    if(sim.mission.status!=='locked')el.innerHTML=missionJournal()+el.innerHTML;
    for(const canvas of el.querySelectorAll('canvas')){const part=canvas.dataset.part,c=canvas.getContext('2d');drawOrganism(c,{x:65,y:75,r:25,angle:-.35,parts:{[part]:sim.player.acquired[part]},player:true,id:0},sim.time,1.2,true);if(part==='segments')drawOrganism(c,{x:28,y:90,r:14,parts:{},player:true,id:1},sim.time);}
  }
  if(kind==='reset'){
    el.innerHTML=`<span class="modal-eyebrow">${t('reset.kicker')}</span><h2 class="modal-title">${t('reset.title')}</h2><p class="modal-copy">${t('reset.copy')}</p><div class="pause-actions"><button class="primary" id="confirm-reset">${t('reset.confirm')}</button><button class="secondary" id="cancel-reset">${t('reset.cancel')}</button></div>`;
    $('#cancel-reset').onclick=()=>{currentModal='pause';renderModal('pause');};$('#confirm-reset').onclick=async()=>{if(lives.length<MAX_LIVES){const life=newLife(null);try{lives=await durable.write(lives,life);}catch{alert(t("notice.saveBody"));return;}await durable.select(life.id);}location.reload();};
  }
}
const medalIcon='<svg class="mission-medal" viewBox="0 0 64 76" aria-hidden="true"><path d="M16 39 10 73 27 62 32 72 39 61 54 73 48 39" fill="#688fc8" stroke="#a8cfff"/><circle cx="32" cy="29" r="25" fill="#aa7935" stroke="#ffe49b" stroke-width="3"/><circle cx="32" cy="29" r="19" fill="#f0cf79"/><path d="m32 14 4 10 11 1-9 7 3 11-9-6-9 6 3-11-9-7 11-1Z" fill="#8f612b"/></svg>';
// Editorial history groups milestones retrospectively; ideas are explicitly uncommitted.
function releaseScreen(){
 const version=document.querySelector('[data-game-version]').textContent;
 return `<span class="modal-eyebrow">${t('release.kicker')}</span><h2 class="modal-title">${t('release.title')}</h2><p class="modal-copy">${t('release.intro')}</p>
 <section class="release-current"><div class="release-status"><b>${version}</b><span>${t('release.available')}</span></div><h3>${t('release.current')}</h3><ul>${['anatomy','attacks','return'].map(key=>`<li>${t('release.'+key)}</li>`).join('')}</ul><p>${t('release.refinements')}</p></section>
 <section class="release-history"><h3>${t('release.history')}</h3><p>${t('release.historyNote')}</p><ol>${[1,2,3,4,5,6,7].map(n=>`<li${n===7?' class="latest"':''}><span class="release-step">V0.${n}</span><div><h4>${t('release.m'+n+'Title')}</h4><p>${t('release.m'+n)}</p></div></li>`).join('')}</ol></section>
 <section class="release-ideas"><h3>${t('release.ideas')}</h3><p>${t('release.ideaNote')}</p><div class="release-ideas-grid">${[1,3].map(n=>`<article><span>${t('release.ideaStatus')}</span><h4>${t('release.idea'+n)}</h4><p>${t('release.idea'+n+'Body')}</p></article>`).join('')}</div></section>
 <footer class="release-policy"><b>${t('release.next')}</b><p>${t('release.policy')}</p><button class="secondary" id="release-close">${t('nav.close')}</button></footer>`;
}
function nestDescription(){const n=sim.nest;return t('nest.stage.'+n.stage);}
function nestProgressText(){const n=sim.nest;if(n.stage==='build')return ['fiber','thread','shell'].map(k=>t('nest.material.'+k)+' '+n.built[k]+'/'+NEST_MATERIALS[k]).join(' · ');if(n.stage==='protect')return n.spines+'/10 · '+t('nest.carried')+': '+n.bag.spine;if(n.stage==='courtship')return t('nest.courtProgress',{trust:Math.floor(n.trust),level:progression(sim.player.xp).level});if(n.stage==='gestation')return t('nest.pregnancy',{percent:Math.floor(n.gestation/90*100)});if(n.stage==='bonding')return Math.floor(n.bonding/6*100)+'%';if(n.stage==='escort')return t('nest.escortProgress');if(n.stage==='egg')return Math.floor(n.incubation/180*100)+'% · '+t(sim.nestThreat?'nest.threat':n.fed>0?'nest.growing':'nest.hungry');return '';}
function nestGuide(){const target=nestTarget(sim);if(!target||sim.nest.stage==='companion')return '';const a=Math.atan2(target.y-sim.player.y,target.x-sim.player.x),arrow=['→','↘','↓','↙','←','↖','↑','↗'][(Math.round(a/(Math.PI/4))+8)%8];return arrow+' '+t('nest.guide',{distance:number(Math.round(dist(target,sim.player)))});}
function nestScreen(){const n=sim.nest;return `<section class="nest-campaign"><span class="modal-eyebrow">${t('nest.campaign')}</span><h2 class="modal-title">${t('nest.title')}</h2><p>${nestDescription()}</p><b>${nestProgressText()}</b><p class="nest-guidance">${nestGuide()}</p><div class="nest-materials">${Object.entries(NEST_MATERIALS).map(([k,max])=>`<div><b>${t('nest.material.'+k)}</b><span>${t('nest.carried')} ${n.bag[k]} · ${t('nest.placed')} ${k==='spine'?n.spines:n.built[k]}/${max}</span></div>`).join('')}</div><p>${t('nest.food',{food:n.food})}</p><p>${t('nest.instructions')}</p><ol class="nest-steps">${NEST_STAGES.map((stage,i)=>`<li class="${i<NEST_STAGES.indexOf(n.stage)?'done':stage===n.stage?'current':''}">${t('nest.name.'+stage)}</li>`).join('')}</ol><div class="nest-medals">${['home','egg','companion'].map(id=>`<span class="${n.medals.includes(id)?'earned':''}">${medalIcon}${t('nest.medal.'+id)}</span>`).join('')}</div></section>`;}
function questTitle(q){return t(q.id==='first'?'mission.title':'journey.name.'+q.id);}
function questMedal(q){return t(q.id==='first'?'mission.medal':['cartographer','evolving'].includes(q.id)?'quests.'+q.id+'Medal':'journey.name.'+q.id);}
function questObjective(q){return q.id==='first'?t('mission.objective'):t('journey.'+q.metric,{target:number(q.target)});}
function questProgress(q){return q.id==='first'?(sim.mission.status==='locked'?t('quests.wait',{minutes:number(Math.max(1,Math.ceil((600-sim.time)/60)))}):missionProgress()):number(Math.min(q.target,missionValue(sim,q)),q.metric==='explore'?1:0)+' / '+number(q.target);}
function bossCollection(){return `<section class="nest-campaign"><h3>${t('boss.name')} · ${sim.boss.cleared.length}/${sim.bossGates.length}</h3><p>${t('boss.findDoor')}</p><div class="boss-medals">${sim.bossGates.map(g=>`<span>${sim.boss.cleared.includes(g.id)?'✦':'◇'} ${t(guardianKey(g.id))} · ${t('biome.'+sim.world.rooms[g.destination].biome+'.name')} · ${t(sim.boss.cleared.includes(g.id)?'boss.openDoor':'boss.locked')}</span>`).join('')}</div></section>`;}
function missionsScreen(){
 const cards=MISSION_CATALOG,count=cards.filter(q=>missionDone(sim,q)).length,next=nextMission(sim);
 return bossCollection()+nestScreen()+`<span class="modal-eyebrow">${t('quests.kicker')}</span><div class="quests-heading"><h2 class="modal-title">${t('quests.title')}</h2><span>${count} / 30 ${t('quests.medals')}</span></div><p class="modal-copy">${t('journey.intro')}</p>${[0,1,2,3,4].map(ch=>{const list=cards.filter(q=>q.chapter===ch),open=chapterOpen(sim,ch);return `<details class="quest-chapter" ${next?.chapter===ch?'open':''}><summary><b>${ch+1}. ${t('journey.chapter.'+ch)}</b><span>${list.filter(q=>missionDone(sim,q)).length} / 6 · ${t(list.every(q=>missionDone(sim,q))?'quests.completed':open?'quests.active':'quests.locked')}</span></summary><div class="quest-list">${list.map(q=>{const done=missionDone(sim,q),locked=!open||q.id==='first'&&sim.mission.status==='locked',fraction=done?1:Math.min(1,missionValue(sim,q)/q.target);return `<article class="quest-card ${done?'earned':locked?'locked':'active'}"><div class="quest-symbol">${medalIcon}<span>${String(cards.indexOf(q)+1).padStart(2,'0')}</span></div><div class="quest-detail"><span class="quest-state">${t(done?'quests.completed':locked?'quests.locked':'quests.active')}</span><h3>${questTitle(q)}</h3><p>${questObjective(q)}</p><div class="quest-track" role="progressbar" aria-label="${questTitle(q)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(fraction*100)}"><i style="width:${fraction*100}%"></i></div><small>${done?t('quests.completed'):!open?t('journey.unlock'):questProgress(q)}</small><div class="quest-reward"><b>${questMedal(q)}</b><span>${t('quests.reward',{xp:number(q.xp)})}</span></div></div></article>`;}).join('')}</div></details>`;}).join('')}<details class="quest-chapter"><summary>${t('quests.collection')} · ${count} / 30</summary><div class="medal-collection">${cards.map(q=>`<div class="medal-item ${missionDone(sim,q)?'earned':'locked'}">${medalIcon}<b>${questMedal(q)}</b><small>${t(missionDone(sim,q)?'quests.completed':'quests.locked')}</small></div>`).join('')}</div></details><button id="quests-play" class="primary">${t('quests.play')}</button>`;
}
function missionProgress(){return t('mission.progress',{centers:number(sim.mission.centers.length),bonus:number(sim.mission.bonus?1:0)});}
function missionJournal(){return sim.mission.status==='completed'?`<article class="mission-award">${medalIcon}<div><h3>${t('mission.medal')}</h3><p>${t('mission.earned')}</p><small>${t('mission.reward')}</small></div></article>`:`<article class="mission-award"><div><h3>${t('mission.title')}</h3><p>${t('mission.objective')}</p><b>${missionProgress()}</b><p>${t('mission.reward')}</p></div></article>`;}
function drawAtlas(){const canvas=$('#atlas-map');if(canvas)renderer.drawMap(canvas,true);}
function closeModal(){if(!currentModal)return;$('#overlay').close();currentModal=null;sim.paused=false;sound.pause(false);pointer.active=false;keys.clear();boostQueued=false;survivalQueued=false;$('#world').focus({preventScroll:true});}
function readInput(){let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(!x&&!y&&Math.hypot(controller.motion.x,controller.motion.y)>0){x=controller.motion.x;y=controller.motion.y;}if(!sim.boss.active&&!x&&!y&&pointer.active){const px=renderer.w/2+(sim.player.x-sim.camera.x)*renderer.zoom,py=renderer.h/2+(sim.player.y-sim.camera.y)*renderer.zoom,dx=pointer.x-px,dy=pointer.y-py,d=Math.hypot(dx,dy),power=clamp((d-18)/150,0,1);x=d?dx/d*power:0;y=d?dy/d*power:0;}const view=renderer.bossView,aim=mouseShooting&&view?{x:(pointer.x-view.ox)/view.s,y:(pointer.y-view.oy)/view.s}:null;const result={x,y,boost:boostQueued,survival:survivalQueued,fire:keys.has('z')||mouseShooting||!!controller.buttons[7],aim};boostQueued=false;survivalQueued=false;return result;}
function applyControllerActions(actions){
  if(document.activeElement instanceof HTMLInputElement||document.activeElement instanceof HTMLSelectElement)return;
  for(const action of actions){
    if(action==='pause'){if(currentModal)closeModal();else if(sim.started)openModal('pause');continue;}
    if(action==='atlas'&&sim.started){currentModal==='atlas'?closeModal():openModal('atlas');continue;}
    if(action==='journal'&&sim.started){currentModal==='journal'?closeModal():openModal('journal');continue;}
    if(action==='secondary'&&sim.started&&sim.boss.active&&!currentModal){if(bossInteract(sim))save();continue;}
    if(action==='secondary'&&sim.started&&!currentModal){openModal('metamorphosis');continue;}
    if(action==='survival'&&sim.started&&!currentModal)survivalQueued=true;
    if(action==='primary'){if(!sim.started)start();else if(!currentModal)boostQueued=true;}
  }
}
function companionHealthText(){const c=companionState(sim);return c.recovery>0?t('companion.recovery',{seconds:Math.ceil(c.recovery)}):t('companion.health',{hp:Math.ceil(c.health)});}
function bossHud(){
 const a=sim.boss.active,near=nearbyBossGate(sim),gate=near||nextBossGate(sim);document.body.classList.toggle('boss-active',!!a);$('#boss-hud').hidden=!a;
 const action=$('#boss-action');action.hidden=!sim.started||!a&&!gate;
 if(!a){action.disabled=!near;action.textContent=near?t(sim.boss.cleared.includes(near.id)?'boss.rematch':'boss.enter'):gate?t('boss.guide',{distance:Math.round(Math.hypot(gate.x-sim.player.x,gate.y-sim.player.y))}):'';sound.setEncounter(0);return;}
 sound.setEncounter(a.phase==='corridor'?a.corridor+1:a.phase==='won'?0:5,a.gate);
 $('#boss-title').textContent=t(a.phase==='corridor'?'boss.entry':guardianKey(a.gate))+' · '+a.gate;
 $('#boss-instruction').textContent=t(a.phase==='corridor'?'boss.corridor'+a.corridor:a.phase==='reveal'?'boss.awaken':a.phase==='arms'?guardianKey(a.gate,'hint'):a.phase==='opening'||a.phase==='core'?guardianKey(a.gate,'core'):a.phase==='won'?(a.replay?'boss.replayReward':a.gate===11?'boss.finalReward':'boss.reward'):'boss.collapse');
 $('#boss-health').textContent=t('boss.health',{hp:Math.ceil(a.hp),charges:a.charges});$('#boss-health').style.color=a.hp<30?'#ff9e91':'#aef6e0';
 const total=(a.phase==='arms'||a.phase==='reveal')&&a.arms.length?a.arms.reduce((n,p)=>n+p.hp,0):a.core,max=(a.phase==='arms'||a.phase==='reveal')&&a.arms.length?a.arms.reduce((n,p)=>n+p.max,0):a.coreMax;
 $('#boss-bar').value=total;$('#boss-bar').max=max;$('#boss-bar').hidden=a.phase==='corridor';$('#boss-count').textContent=a.phase==='arms'?t(guardianKey(a.gate,'parts'))+' · '+t('boss.remaining',{count:a.arms.filter(p=>p.hp>0).length,total:a.arms.length}):a.phase==='core'?t(bossVulnerable(a)?'boss.exposed':'boss.protected'):'';
 $('#boss-buffs').textContent=Object.entries(a.buffs).filter(([,v])=>v>0).map(([k,v])=>t('boss.buff.'+k)+' '+Math.ceil(v)+'s').join(' · ');
 $('#boss-baby-health').hidden=sim.nest.stage!=='companion';$('#boss-baby-health').textContent=companionHealthText();
 $('#boss-save').textContent=$('#save-status').textContent;
 let key='boss.closed',ready=false;if(a.phase==='corridor'){if(a.corridor===0&&a.x<180){key='boss.leave';ready=true;}else if(a.corridor===2&&!a.shell){key='boss.chest';ready=Math.abs(a.x-1060)<155;}else if(a.corridor===2&&a.shell){key='boss.begin';ready=a.x>1260;}else key='boss.walk';}else if(a.phase==='won'){key='boss.exit';ready=a.x>1270;}
 action.textContent=t(key);action.disabled=!ready;
}
